CREATE OR REPLACE FUNCTION public.team_notification_access(_team uuid,_link text,_kind text) RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE tm uuid; token text; BEGIN IF _team IS NOT NULL THEN RETURN team_channel_access(_team); END IF; IF _kind NOT IN ('announcement','conversation') OR _link IS NULL OR _link !~ '^/team[?]' THEN RETURN true; END IF; token:=substring(_link from '[?&]team=([0-9a-fA-F-]{36})'); IF token IS NOT NULL THEN BEGIN tm:=token::uuid; EXCEPTION WHEN invalid_text_representation THEN RETURN false; END; ELSE token:=substring(_link from '[?&]topic=([0-9a-fA-F-]{36})'); IF token IS NOT NULL THEN BEGIN SELECT team_id INTO tm FROM discussion_topics WHERE id=token::uuid; EXCEPTION WHEN invalid_text_representation THEN RETURN false; END; END IF; END IF; RETURN tm IS NOT NULL AND team_channel_access(tm); END $$;
CREATE POLICY channel_legacy_notification_read ON public.notifications AS RESTRICTIVE FOR SELECT TO authenticated USING(team_notification_access(communication_team_id,link,kind));
CREATE OR REPLACE FUNCTION public.team_channel_delivery_eligible(_team uuid,_user uuid,_kind text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT team_channel_access(_team,_user) AND NOT EXISTS(SELECT 1 FROM team_channel_preferences WHERE team_id=_team AND user_id=_user AND muted) AND coalesce((SELECT (notify_prefs->>_kind)::boolean FROM profiles WHERE id=_user),true); $$;
REVOKE ALL ON FUNCTION public.team_notification_access(uuid,text,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.team_notification_access(uuid,text,text) TO authenticated,service_role;
REVOKE ALL ON FUNCTION public.team_channel_delivery_eligible(uuid,uuid,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.team_channel_delivery_eligible(uuid,uuid,text) TO service_role;
DO $patch$ DECLARE d text; BEGIN SELECT pg_get_functiondef('public.claim_outbox(integer)'::regprocedure) INTO d; d:=replace(d,'WHEN c.channel = ''sms'' AND EXISTS','WHEN c.event_id IS NULL AND c.team_id IS NOT NULL AND c.kind IN (''announcements'',''conversation'') AND NOT public.team_channel_delivery_eligible(c.team_id,c.user_id,c.kind) THEN ''team_access_or_mute_changed'' WHEN c.channel = ''sms'' AND EXISTS'); EXECUTE d; END $patch$;